from auto_config.generator.utils.logger import logger


def get_env_config(raw_enb, enb_config):
    env_config = {}
    logger.info("Generating ENV.yaml")
    for env_key in raw_enb:
        if env_key.startswith('profile_'):
            continue
        env_config[env_key] = raw_enb[env_key]

    env_config['HOST_DOMAIN'] = '10.0.1.1'
    env_config['EMSSIM_IP'] = '10.0.1.1'
    env_config['EMSSIM_OAM_IP'] = '10.0.1.1'
    env_config['EPCSIM_EGATE_PORT'] = 20000
    env_config['EPCSIM_EDAEMON_PORT'] = 10000

    for enb_ent_config in enb_config.values():
        enb_num = int(enb_ent_config['num'])
        if enb_num > 100:
            continue
        if enb_num == 1:
            env_config['EMSSIM_CLI_PORT'] = 7001
            env_config['EMSSIM_RPC_PORT'] = 4001

        env_config[f'EMSSIM_CLI_PORT_{enb_num}'] = 7000 + enb_num
        env_config[f'EMSSIM_RPC_PORT_{enb_num}'] = 4000 + enb_num

    return env_config
